#!/usr/bin/env python3
# setup_ring_v1: XpertChat calls ring the phone, even when the app is closed
#  - the call notification has Answer and Decline buttons, a long vibration, stays on screen, and rings again
#    every 7 seconds while the call is ringing (about 35 seconds); Decline works without opening the app
#  - call notifications are sent as "urgent" so Android delivers them at once (also when the phone is asleep),
#    and they expire after 40 seconds, so an old call never pops up later; a missed call replaces the ringing one
#  - the caller sees "Ringing..." only when the other phone can ring; if that person has notifications off,
#    the caller sees "Calling..." and a short note
#  - chat and group pages show a "Get calls even when the app is closed - Turn on" bar to members whose phone
#    has notifications off (or how to unblock them); the notification card also mentions calls now
# Run without --apply first (dry run). Prints no passwords or keys.
import base64, glob, json, os, re, shutil, subprocess, sys, time
from datetime import datetime

API, LAND, ACAD = "/var/www/xpertcreation-api", "/var/www/xpertcreation-landing", "/var/www/xpertacademy"
PUSH, CV, CU = API + "/notifications/push.py", API + "/xcalls/views.py", API + "/xcalls/urls.py"
SW, XJ, TOP = LAND + "/sw.js", LAND + "/js/xcall-1.js", LAND + "/js/topnav-1.js"
fail = []


def need(label, ok, note=""):
    print("  %-56s %s" % (label[:56], ("ok" if ok else "PROBLEM") + (" " + note if note else "")))
    if not ok:
        fail.append(label)


def bye(c):
    os.chdir("/root"); sys.exit(c)


def sh(c, t=600):
    r = subprocess.run(c, shell=True, capture_output=True, text=True, timeout=t)
    return r.returncode, ((r.stdout or "") + (r.stderr or "")).strip()


def rd(p):
    try:
        return open(p, encoding="utf-8").read()
    except Exception:
        return ""


def code(p, method="GET"):
    return sh("curl -sk -o /dev/null -w '%%{http_code}' -X %s -H 'Host: xpertcreation.com' -H 'Content-Type: application/json' %s 'https://127.0.0.1%s'"
              % (method, "-d '{}'" if method == "POST" else "", p))[1]


